import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { ScrollView, TouchableOpacity, Image, FlatList } from 'react-native';
import { useRouter } from 'expo-router';
import tw from 'twrnc';
import Searchbar from '../../components/Searchbar';
import LanguageList from '../../components/LanguageList';
import { useThemeColor } from '@/hooks/useThemeColor';
import { ThemedText } from '@/components/ThemedText';
import { ThemedView } from '@/components/ThemedView';
import Constants from 'expo-constants';

export default function Main() {
  const [books, setBooks] = useState([]); 
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const backgroundColor = useThemeColor({}, 'background');
  const textColor = useThemeColor({}, 'text');
  const primaryColor = useThemeColor({}, 'primary');

 
  const apiUrl = Constants.expoConfig?.extra?.API_BASE_URL;
${apiUrl}
  useEffect(() => {
    axios.get(`/books`, {
        headers: {
          'Content-Type': 'application/json',
        },
      })
      .then((res) => {
        if (Array.isArray(res.data)) {
          setBooks(res.data); // Ensure data is an array before setting state
        } else {
          setBooks([]); // Fallback to an empty array
        }
        setLoading(false);
      })
      .catch((error) => {
        setError(error.message);
        setLoading(false);
      });
  }, []); // Removed unnecessary dependency array

  if (loading) {
    return (
      <ThemedView style={[tw`flex-1 items-center justify-center`, { backgroundColor }]}>
        <ThemedText style={{ color: textColor }}>Loading...</ThemedText>
      </ThemedView>
    );
  }

  if (error) {
    return (
      <ThemedView style={[tw`flex-1 items-center justify-center`, { backgroundColor }]}>
        <ThemedText style={{ color: textColor }}>Error: {error}</ThemedText>
      </ThemedView>
    );
  }

  return (
    <ThemedView style={[tw`flex-1`, { backgroundColor }]}>
      <ScrollView>
        <ThemedView style={tw`ml-5 mt-12`}>
          <ThemedText type ='title' style={{ color: textColor }} >Iweohun</ThemedText>
          <ThemedText style={[tw`text-xl font-semibold`, { color: '#ff1493' }]}>
            Orating African literature
          </ThemedText>
        </ThemedView>

        <Searchbar />
        <LanguageList />

        <ThemedView style={tw`mb-10 w-full mx-5`}>
          {['History & Biographies', 'Fiction & Romance', 'Kids', 'Personal Development', 'Adventure & Thrillers'].map((category) => (
            <CategorySection
              key={category}
              title={category}
              books={books}
              textColor={textColor}
              primaryColor={primaryColor}
            />
          ))}
        </ThemedView>
      </ScrollView>
    </ThemedView>
  );
}

function CategorySection({ title, books, textColor, primaryColor }) {
  const router = useRouter();

  // Ensure books is always an array
  const filteredBooks = Array.isArray(books) ? books.filter((book) => book.category === title) : [];

  return (
    <ThemedView style={tw`ml-5 mb-5`}>
      <ThemedText style={[tw`text-2xl mb-3 font-bold`, { color: textColor }]}>{title}</ThemedText>
      {filteredBooks.length > 0 ? (
        <FlatList
          horizontal
          showsHorizontalScrollIndicator={false}
          data={filteredBooks}
          keyExtractor={(item) => item.id?.toString() || Math.random().toString()}
          renderItem={({ item }) => (
            <TouchableOpacity
              onPress={() => router.push(`/book/${item.id}`, { book: item })}
              style={tw`mr-3`}
            >
              <Image
                source={{ uri: item.bookCover }}
                style={tw`w-20 h-25 rounded-lg mr-4`}
              />
            </TouchableOpacity>
          )}
        />
      ) : (
        <ThemedText style={[tw`text-base`, { color: textColor }]}>
          No books available in this category.
        </ThemedText>
      )}
    </ThemedView>
  );
}
